mapper.select:
SELECT d.task_id,d.target_version_id,v.version_number AS target_version_number,d.created_at AS adopted_at,
  t.purpose,t.manifest_json,t.manifest_hash
FROM ai_card_draft_decision d
JOIN memory_card_version v ON v.owner_id=d.owner_id AND v.card_id=d.target_card_id AND v.id=d.target_version_id
JOIN ai_task t ON t.owner_id=d.owner_id AND t.id=d.task_id
WHERE d.owner_id=#{owner} AND d.target_card_id=#{cardId} AND d.status='ADOPTED' AND v.version_number <=#{through}
AND v.version_number < #{before}
ORDER BY v.version_number DESC LIMIT #{limit}
